def write(root: Path, *, hooks: bool = False) -> Path:
    variant = "hooks" if hooks else "plain"
    built = support.synthetic_manifest(root, live=True, executor_name="claude_live")
    data = built.data
    data["pins"] = INPUTS[variant + "_pins"]
    data["arms"] = INPUTS[variant + "_arms"]
    data["tasks"][0]["id"] = "actor" if hooks else "answer-file"
    data["repeats"] = 1
    for arm in data["arms"]:
        arm["settings_hash"] = "sha256:" + sha256_json(arm["settings"])
    built.path.write_text(json.dumps(data), encoding="utf-8")
    manifest.load(built.path)
    return built.path
